import{_ as a,o as t,c as s,a4 as r}from"./chunks/framework.CzJ_HCFe.js";const u=JSON.parse('{"title":"Guest birth profiles and the D1 Rashi chart","description":"","frontmatter":{},"headers":[],"relativePath":"reference/53-birth-profile-calculation.md","filePath":"reference/53-birth-profile-calculation.md","lastUpdated":1788414836000}'),i={name:"reference/53-birth-profile-calculation.md"};function o(n,e,d,l,c,h){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="guest-birth-profiles-and-the-d1-rashi-chart" tabindex="-1">Guest birth profiles and the D1 Rashi chart <a class="header-anchor" href="#guest-birth-profiles-and-the-d1-rashi-chart" aria-label="Permalink to &quot;Guest birth profiles and the D1 Rashi chart&quot;">​</a></h1><p>This page explains the birth-details calculation used by guest Profiles. It is for people checking what leaves the browser, how Nakshatra and the chart are derived, and what “verified” does and does not mean.</p><blockquote><p><strong>Current assurance:</strong> documented, traceable, and reproduced through a second formula path. The three fixture cells are not an independent published-chart comparison because both paths use Swiss Ephemeris. Public activation remains gated on the separate Swiss Ephemeris and PySwissEph wrapper decision, producer-contract invariants, managed geocoding/shared abuse controls, and the <a href="./../operations/guest-calculation-production-activation">three-service Preview runbook</a>. That hosted Preview runbook is currently blocked: the deployed clients cannot yet bind an exact Panchangam Preview to exact Astro and DashaFlow Previews.</p></blockquote><blockquote><p><strong>Activation state:</strong> the birth-details interface and network adapter are on by default only for loopback development. A public build must set <code>VITE_BIRTH_PROFILE_API_ENABLED=true</code>, where <code>true</code> is the exact, case-sensitive value; every other explicit value fails closed. When inactive, Profiles defaults to manual entry and keeps existing calculated profiles viewable without permitting recalculation or editing.</p></blockquote><h2 id="meaning" tabindex="-1">Meaning <a class="header-anchor" href="#meaning" aria-label="Permalink to &quot;Meaning&quot;">​</a></h2><p>A birth profile turns an exact local date, time, and selected birthplace into:</p><ul><li>Janma Nakshatra and Padam;</li><li>Janma Rashi;</li><li>Lagna and its degree within the Rashi;</li><li>the sidereal Rashi and Whole Sign house of Surya, Chandra, Kuja, Budha, Guru, Shukra, Shani, mean Rahu, and Ketu; and</li><li>a South Indian D1 Rashi chart.</li></ul><p>The profile reuses Nakshatra and Padam in Muhurtam and Daily Horoscope. The D1 chart is a positional reference only. This contract does not return Dasha, Yoga, compatibility, predictions, or interpretive claims from DashaFlow.</p><h2 id="inputs-and-privacy-boundary" tabindex="-1">Inputs and privacy boundary <a class="header-anchor" href="#inputs-and-privacy-boundary" aria-label="Permalink to &quot;Inputs and privacy boundary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Input</th><th>Where it goes</th><th>Why</th></tr></thead><tbody><tr><td>Profile name</td><td>Browser storage only</td><td>A local label for recognizing the person; it is rejected by the calculation gateway.</td></tr><tr><td>Place search text</td><td>Astro Chaganti gateway, then the geocoder</td><td>Returns at most five selectable places. Use a city or town, not a street address.</td></tr><tr><td>Selected latitude, longitude, and IANA timezone</td><td>Astro Chaganti gateway and DashaFlow sidecar</td><td>Resolves the birth instant and location-dependent ascendant.</td></tr><tr><td>Local date and exact local time</td><td>Astro Chaganti gateway and DashaFlow sidecar</td><td>Resolves the UTC instant used by the ephemeris.</td></tr><tr><td>Calculated result and original inputs</td><td>Origin-scoped browser <code>localStorage</code></td><td>Reuses the profile without an account or repeated calculation.</td></tr></tbody></table><p>When the capability is active, the browser calls the server only after <strong>Find place</strong> or <strong>Calculate details</strong>. Application code does not create an Astro Chaganti account, database row, or analytics event from these values. Network and hosting providers necessarily process requests in transit; do not interpret “browser-local profile” as “no network calculation.” The application does not load third-party executable analytics code on this profile-bearing origin, and built-in share text omits the saved profile name. There is no cloud sync or recovery.</p><pre class="mermaid">flowchart LR
  UI[&quot;Panchangam static UI&quot;] --&gt;|&quot;place text only&quot;| PLACE[&quot;Astro guest place route&quot;]
  PLACE --&gt; GEO[&quot;Owner-approved managed geocoder&lt;br/&gt;(selection pending)&quot;]
  PLACE --&gt; TZ[&quot;offline coordinate-to-timezone lookup&quot;]
  UI --&gt;|&quot;date, time, coordinates, timezone; no name&quot;| GATEWAY[&quot;Astro guest profile route&quot;]
  GATEWAY --&gt;|&quot;server bearer credential&quot;| SIDE[&quot;DashaFlow sidecar v1 contract&quot;]
  SIDE --&gt; CALC[&quot;DashaFlow 1.1.0 + PySwissEph&quot;]
  CALC --&gt;|&quot;narrow result; no raw input echo&quot;| UI
  UI --&gt; STORE[&quot;browser profile storage&quot;]
</pre><p>The Astro gateway permits the Panchangam production origin and HTTP localhost origins, caps bodies at 4 KiB, rate-limits requests, and marks responses <code>private, no-store</code>. Its DashaFlow bearer token is server-only and must never be placed in browser code or a <code>VITE_*</code> variable. The reviewed gateway PR head has a shared deployed limiter for election charts but only per-instance limiters for place and birth requests. A local remediation candidate expands the shared guest limit, but it is not a recorded release or hosted certification and it does not provide a shared geocoder cache. <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/446" target="_blank" rel="noreferrer">#446</a> must close and verify those controls before activation.</p><p>The build flag is not authorization and contains no secret. A public page uses only the canonical <code>https://astrochaganti.com/api/guest</code> HTTPS gateway; a loopback or arbitrary configured base is rejected. Consequently, <code>VITE_BIRTH_PROFILE_API_BASE</code> cannot select a hosted Astro Preview today. Astro also rejects a hosted Panchangam Preview origin, so end-to-end Preview certification remains blocked until an exact pair-bound mechanism is approved and implemented. Public activation requires both the exact client flag and independently enabled server-side routes. The server must remain disabled until the licensing and provider gates below are resolved. A disabled browser adapter throws a typed <code>disabled</code> error before it creates a timeout or calls <code>fetch</code>.</p><h2 id="local-storage-transaction" tabindex="-1">Local storage transaction <a class="header-anchor" href="#local-storage-transaction" aria-label="Permalink to &quot;Local storage transaction&quot;">​</a></h2><p>Calculated profiles use a three-key browser transaction: the legacy-compatible base profile array, a revision-bound birth-data envelope, and a commit marker. The marker is written last and records both the revision and the exact base payload. A reader attaches birth data only when all three values agree; base or envelope events observed before the marker therefore load fail-closed without attaching a mismatched chart.</p><p>If any write fails, the store does not automatically delete or roll back keys: multi-key <code>localStorage</code> has no atomic fence that could prevent such cleanup from overwriting a newer tab. Existing companion bytes remain untouched until their own write step; an absent or mismatching marker keeps every partial new base or envelope detached.</p><p>When the base key is absent, confirmed recovery is offered only when every present companion exactly matches the store&#39;s current recognized format; when both companions are present, their revision and base relationships must also agree. This is conservative format recognition, not proof of which code wrote the bytes. Unrecognized or future-format bytes remain read-only. A base-present torn transaction can be replaced only by an explicit user reset or later successful save. The failure points, cross-tab boundary, and orphan rules are pinned in <a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/src/__tests__/guest-profile-store.test.ts" target="_blank" rel="noreferrer"><code>src/__tests__/guest-profile-store.test.ts</code></a>.</p><h2 id="calculation-process" tabindex="-1">Calculation process <a class="header-anchor" href="#calculation-process" aria-label="Permalink to &quot;Calculation process&quot;">​</a></h2><h3 id="response-and-saved-record-validation" tabindex="-1">Response and saved-record validation <a class="header-anchor" href="#response-and-saved-record-validation" aria-label="Permalink to &quot;Response and saved-record validation&quot;">​</a></h3><p>The browser accepts contract version <code>1.0</code>, engine name <code>DashaFlow</code>, a non-empty engine version, and <code>Lahiri</code> ayanamsha. It requires the canonical Rashi and Nakshatra spellings and exactly this ordered nine-graha tuple:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Surya, Chandra, Kuja, Budha, Guru, Shukra, Shani, Rahu, Ketu</span></span></code></pre></div><p>The fields are also checked against each other rather than trusted as independent labels. The reported Nakshatra and Padam must derive the reported Janma Rashi, and Chandra&#39;s Rashi must equal that Janma Rashi. Because the service projects Chandra&#39;s degree within its Rashi to two decimals, the browser treats that displayed degree as a closed ±0.005° interval, clipped to the Rashi. The reported Nakshatra-Padam cell is accepted only when at least one longitude in that interval belongs to the cell. This admits an honestly rounded boundary value without allowing an incompatible Moon position.</p><p>Each graha&#39;s reported house must also equal the Whole Sign house derived from the reported Lagna and graha Rashi. Surya and Chandra must be direct; Rahu and Ketu must be retrograde; and the rounded Rahu/Ketu positions must remain opposite within the maximum 0.01° separation error introduced by rounding both ends to two decimals.</p><p>The same canonical metadata, graha order, and cross-field relationships are checked before a calculated extension read from <code>localStorage</code> is attached to its base profile. Malformed, reordered, future-contract, or internally inconsistent calculated data fails closed to the manual-profile view; it is not silently presented as a verified D1 result.</p><h3 id="_1-resolve-the-birth-instant" tabindex="-1">1. Resolve the birth instant <a class="header-anchor" href="#_1-resolve-the-birth-instant" aria-label="Permalink to &quot;1. Resolve the birth instant&quot;">​</a></h3><p>The exact <code>YYYY-MM-DD</code> date and <code>HH:MM</code> time are interpreted as local civil time in the selected IANA timezone. DashaFlow converts that value to UTC and then to a Universal-Time Julian day:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>local civil date/time + IANA timezone</span></span>
<span class="line"><span>  -&gt; timezone-aware local instant</span></span>
<span class="line"><span>  -&gt; UTC instant</span></span>
<span class="line"><span>  -&gt; Julian day UT</span></span></code></pre></div><p>The IANA identifier matters because a numeric offset alone cannot represent historical daylight-saving and government rule changes.</p><p>Before sending a calculation request, the browser resolves that same wall time in the selected birthplace timezone. Its latest selectable date is the current civil date there, not the computer&#39;s UTC or local date. A future instant, an invalid timezone, or an ambiguous or nonexistent daylight-saving wall time is rejected in the form instead of being silently assigned an offset.</p><h3 id="_2-select-the-astronomical-convention" tabindex="-1">2. Select the astronomical convention <a class="header-anchor" href="#_2-select-the-astronomical-convention" aria-label="Permalink to &quot;2. Select the astronomical convention&quot;">​</a></h3><p>DashaFlow explicitly selects Lahiri sidereal mode and uses:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FLG_SIDEREAL | FLG_SPEED</span></span></code></pre></div><p>for the graha positions. The positions are geocentric; this contract does not set the topocentric flag. Swiss Ephemeris documentation requires the sidereal flag and an explicit sidereal mode for a chosen ayanamsha.</p><p>The returned <code>engine.ephemeris</code> is read from the actual Swiss Ephemeris return flags. It is <code>swiss</code>, <code>moshier</code>, or <code>unknown</code>. It is never inferred from the requested flags or package name. Swiss Ephemeris can fall back to Moshier when the requested data files are not present, which is why this disclosure is part of every saved profile.</p><p>Technical reference: <a href="https://www.astro.com/swisseph/swephprg.htm" target="_blank" rel="noreferrer">Swiss Ephemeris Programmer&#39;s Documentation</a>, sections 3, 12, and 15.4.</p><h3 id="_3-derive-nakshatra-padam-and-janma-rashi" tabindex="-1">3. Derive Nakshatra, Padam, and Janma Rashi <a class="header-anchor" href="#_3-derive-nakshatra-padam-and-janma-rashi" aria-label="Permalink to &quot;3. Derive Nakshatra, Padam, and Janma Rashi&quot;">​</a></h3><p>Let <code>M</code> be the normalized sidereal Moon longitude in <code>[0°, 360°)</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nakshatra_span = 360° / 27</span></span>
<span class="line"><span>pada_span       = 360° / 108</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nakshatra_index = floor(M / nakshatra_span)</span></span>
<span class="line"><span>degree_in_star  = M - nakshatra_index * nakshatra_span</span></span>
<span class="line"><span>pada            = floor(degree_in_star / pada_span) + 1</span></span>
<span class="line"><span>janma_rashi     = floor(M / 30°)</span></span></code></pre></div><p>Indices select the canonical 27-Nakshatra and 12-Rashi name tables. The sidecar normalizes DashaFlow spellings such as <code>Ashwini</code> and <code>Dhanishta</code> to the existing Panchangam vocabulary <code>Ashvini</code> and <code>Dhanishtha</code>.</p><h3 id="_4-derive-lagna-and-whole-sign-houses" tabindex="-1">4. Derive Lagna and Whole Sign houses <a class="header-anchor" href="#_4-derive-lagna-and-whole-sign-houses" aria-label="Permalink to &quot;4. Derive Lagna and Whole Sign houses&quot;">​</a></h3><p>The ascendant is the first value in <code>ascmc</code> returned by:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>houses_ex(julian_day_ut, latitude, longitude, &quot;W&quot;, sidereal_flags)</span></span></code></pre></div><p><code>W</code> is the Whole Sign house method. If <code>L</code> is the Lagna Rashi index and <code>P</code> is a graha&#39;s Rashi index, the house number is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>house = ((P - L) mod 12) + 1</span></span></code></pre></div><p>The <a href="https://www.astro.com/swisseph/swephprg.htm" target="_blank" rel="noreferrer">Swiss house-function reference</a> supports the UT, coordinate, sidereal-flag, and house-method API semantics. It does not by itself establish a textual Jyotisha authority for choosing Lahiri or Whole Sign houses; those are explicit product conventions.</p><h3 id="_5-derive-the-nine-displayed-grahas" tabindex="-1">5. Derive the nine displayed grahas <a class="header-anchor" href="#_5-derive-the-nine-displayed-grahas" aria-label="Permalink to &quot;5. Derive the nine displayed grahas&quot;">​</a></h3><p><code>calc_ut</code> supplies Surya, Chandra, Kuja, Budha, Guru, Shukra, Shani, and mean Rahu. Ketu is placed exactly 180° from Rahu:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ketu_longitude = (rahu_longitude + 180°) mod 360°</span></span></code></pre></div><p>Surya and Chandra are always represented as direct. Rahu and Ketu are always represented as retrograde. The other grahas are retrograde when their returned longitudinal speed is negative. Degrees within a Rashi are rounded to two decimal places for this contract.</p><h2 id="reproduction-fixture" tabindex="-1">Reproduction fixture <a class="header-anchor" href="#reproduction-fixture" aria-label="Permalink to &quot;Reproduction fixture&quot;">​</a></h2><p>The repository pins three synthetic cells across India, North America, and Europe in <a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/tests/fixtures/birth_profile_reference.json" target="_blank" rel="noreferrer"><code>tests/fixtures/birth_profile_reference.json</code></a>. For example:</p><table tabindex="0"><thead><tr><th>Input</th><th>Reproduced result</th></tr></thead><tbody><tr><td>1990-04-15 14:30, Hyderabad, <code>Asia/Kolkata</code></td><td>Jyeshtha, Padam 4; Vrischika Janma Rashi; Simha Lagna 4.69°; Moshier</td></tr></tbody></table><p><code>tests/test_birth_profile_reference.py</code> recomputes the narrow contract directly with PySwissEph without importing DashaFlow. That protects the time conversion, longitude partitions, Ketu rule, Whole Sign house rule, canonical names, and two-decimal projection against drift.</p><p>Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/test_birth_profile_reference.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>This is <strong>reproduction checked</strong>, not independently source-compared. A future comparison must name the external chart, its exact input cell, ayanamsha, node, house, ephemeris, and timezone conventions rather than comparing labels alone.</p><h2 id="known-limitations-and-release-gates" tabindex="-1">Known limitations and release gates <a class="header-anchor" href="#known-limitations-and-release-gates" aria-label="Permalink to &quot;Known limitations and release gates&quot;">​</a></h2><ol><li><strong>Swiss Ephemeris and PySwissEph licensing:</strong> Astrodienst requires a developer to choose AGPL-compatible licensing or a Professional License before distributing a derived application or activating a public service. Its current professional contract explicitly covers browser clients that request server-side calculations. PySwissEph is a separately AGPL-licensed wrapper; an unresolved <a href="https://github.com/astrorigin/pyswisseph/issues/92" target="_blank" rel="noreferrer">upstream wrapper-license issue</a> means a Swiss Professional License alone does not establish proprietary-use rights for the current binding. Public activation is blocked until the owner records the applicable combined posture. See <a href="https://www.astro.com/swisseph/swisseph.htm" target="_blank" rel="noreferrer">Astrodienst&#39;s licensing page</a> and <a href="https://www.astro.com/swisseph/secont_e.pdf" target="_blank" rel="noreferrer">Professional License contract</a>. The decision, existing-distribution audit, implementation, and wrapper path are tracked in <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/231" target="_blank" rel="noreferrer">#231</a> with required children <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/444" target="_blank" rel="noreferrer">#444</a>, <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/445" target="_blank" rel="noreferrer">#445</a>, and <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/449" target="_blank" rel="noreferrer">#449</a>.</li><li><strong>Actual ephemeris:</strong> current local fixture calls report Moshier because the deployed data-file posture has not been approved. Production must probe and disclose its own actual return flags; it must not promise Swiss data-file output merely because PySwissEph is installed.</li><li><strong>DST ambiguity:</strong> DashaFlow 1.1.0 itself calls <code>pytz.localize</code> without the fail-closed <code>is_dst=None</code> option. The authenticated sidecar contract therefore validates the complete local civil time first and rejects repeated or skipped wall times instead of letting the library choose a side. Guests with one of these unusual recorded times must use manual profile entry until an explicit first/second-occurrence choice is supported. The <a href="https://pythonhosted.org/pytz/" target="_blank" rel="noreferrer">pytz documentation</a> describes this boundary.</li><li><strong>Historical timezones:</strong> the IANA database itself warns that many pre-1970 records represent only part of a region and are not authoritative everywhere. See <a href="https://www.iana.org/time-zones/theory" target="_blank" rel="noreferrer">IANA timezone theory and limitations</a>.</li><li><strong>Place search policy and cache:</strong> this UI uses an explicit submit action, asks for city/town only, and warns against street addresses. Guest use of public Nominatim is retained for explicit local development only. Astro candidate <code>e7fb3fe6e8e05f47f04aaa1b19ce9447d92ad315</code> accepts only fixed LocationIQ or Geoapify adapters for deployed guest search, rejects redirects and oversized/malformed responses, and returns at most five normalized rows. Deployed cache keys are token-HMAC pseudonyms and the 24-hour shared value contains only normalized labels, coordinates, provider IDs, and ranking metadata—not the raw place query, birth date, birth time, profile name, natal chart, or client IP. Missing or unavailable shared storage fails closed. The browser validates an allowlist of structured provider/OpenStreetMap attribution links and renders them beside results. Provider transit necessarily includes the submitted city/town query; the selected provider&#39;s own retention and quota terms still require approval. Provider approval and implementation certification are tracked in <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/233" target="_blank" rel="noreferrer">#233</a> and <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/446" target="_blank" rel="noreferrer">#446</a>. Existing deployed signed-in profile creation/editing keeps its disclosed Nominatim path while <code>AUTH_PROFILE_MANAGED_GEOCODER_ENABLED</code> is absent or false. Exact <code>true</code> separately migrates it to the same managed adapter, adds a ten-call-per-user limit, and shares the 60-call fleet ceiling with guest search without depending on guest feature flags. That migration still requires provider/Redis approval and Preview regression evidence under <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/447" target="_blank" rel="noreferrer">#447</a>.</li><li><strong>Birth-time sensitivity:</strong> a small time difference can change Lagna near a boundary. The current calculated path accepts exact recorded time only. An unknown or approximate time must use manual entry; no precise Lagna is fabricated.</li><li><strong>Storage scope:</strong> browser data is visible to anyone using the same browser profile and origin. Clearing site data, changing domain/port, or using another device loses access. There is no recovery.</li></ol><h2 id="implementation-ownership-and-review-triggers" tabindex="-1">Implementation ownership and review triggers <a class="header-anchor" href="#implementation-ownership-and-review-triggers" aria-label="Permalink to &quot;Implementation ownership and review triggers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Owner</th><th>Tests</th></tr></thead><tbody><tr><td>Browser API validation</td><td><code>src/lib/birth-profile-api.ts</code></td><td><code>src/__tests__/birth-profile-api.test.ts</code></td></tr><tr><td>Public/local activation policy</td><td><code>src/lib/remote-calculation-activation.ts</code></td><td><code>src/__tests__/remote-calculation-activation.test.ts</code></td></tr><tr><td>Commit-bound fail-closed local storage</td><td><code>src/lib/guest-profile-store.ts</code></td><td><code>src/__tests__/guest-profile-store.test.ts</code></td></tr><tr><td>Profile form, review, and D1 chart</td><td><code>src/panels/profiles.ts</code></td><td><code>src/__tests__/profiles-panel.test.ts</code>, browser smoke tests</td></tr><tr><td>Public stateless gateway</td><td><code>astro-unified-core</code> guest API routes</td><td>route, CORS, rate-limit, body-cap, and contract tests in that repository</td></tr><tr><td>Authenticated calculation projection</td><td><code>dashaflow-sidecar/api/profile.py</code></td><td>sidecar profile-contract tests</td></tr></tbody></table><p>Review this page when any contract version, DashaFlow/PySwissEph version, ayanamsha, node choice, house method, timezone package/data, place provider, rounding rule, storage schema, actual ephemeris, or privacy boundary changes.</p>`,62)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
